1	package main
2	
3	import (
4		"fmt"
5		"math"
6		"sort"
7	)
8	
9	// 维修工单备件领用与退回台账。
10	//
11	// 领用：仅未关闭工单可领用，输入工单编号、非空备件编号、正整数数量（工单用量）
12	// 与非空说明；每次成功生成同目录唯一且不复用的领用编号（P 加补零序号），并追加
13	// 一条领用履历。同备件多次领用各自独立，领用编号用于定位记录，不用报修请求标识
14	// 代替。
15	//
16	// 退回：输入领用编号、正整数数量与非空理由，作用于该笔领用所属的工单；允许多次
17	// 部分退回，累计不得超过该笔原数量，也不能冲减另一笔。成功时更新累计退回并追加
18	// 一条退回履历，净量 = 原数量 - 累计退回。
19	//
20	// 工单关闭或取消后保留领用记录与净量，不自动清零；终结后拒绝领用与退回，
21	// 旧单的记录不影响新工单。领用、退回各为一次原子保存：校验、数量或编号容量
22	// 不足、读写失败时保留原文件字节，不留下部分记录、不消耗编号，恢复后可重试。
23	
24	// findPart 按领用编号查找领用记录，不存在时返回 nil。
25	func (s *store) findPart(id string) *PartWithdrawal {
26		for _, p := range s.data.Parts {
27			if p.ID == id {
28				return p
29			}
30		}
31		return nil
32	}
33	
34	// partsOf 按领用顺序返回工单的全部领用记录（追加顺序即领用顺序）。
35	func (s *store) partsOf(ticketID string) []*PartWithdrawal {
36		out := make([]*PartWithdrawal, 0)
37		for _, p := range s.data.Parts {
38			if p.TicketID == ticketID {
39				out = append(out, p)
40			}
41		}
42		return out
43	}
44	
45	// partNetRow 为按备件编号汇总的一行净量。
46	type partNetRow struct {
47		PartID string
48		Net    int
49	}
50	
51	// partNetSummary 按备件编号字典序汇总工单各笔领用的净量；全部退回的备件
52	// 净量为零仍显示。
53	func (s *store) partNetSummary(ticketID string) []partNetRow {
54		nets := map[string]int{}
55		for _, p := range s.partsOf(ticketID) {
56			nets[p.PartID] += p.Quantity - p.Returned
57		}
58		rows := make([]partNetRow, 0, len(nets))
59		for partID, net := range nets {
60			rows = append(rows, partNetRow{PartID: partID, Net: net})
61		}
62		sort.Slice(rows, func(i, j int) bool { return rows[i].PartID < rows[j].PartID })
63		return rows
64	}
65	
66	// appendPartEvent 以给定序号追加备件履历（领用或退回）。备件履历属于领用记录
67	// 所在的工单，from/to 与保养字段恒为空；content 为领用说明或退回理由。
68	func (s *store) appendPartEvent(seq int, p *PartWithdrawal, kind string, quantity int, content string) {
69		s.data.Events = append(s.data.Events, Event{
70			Seq:          seq,
71			AssetID:      p.AssetID,
72			TicketID:     p.TicketID,
73			Kind:         kind,
74			Content:      content,
75			PartID:       p.PartID,
76			Quantity:     quantity,
77			WithdrawalID: p.ID,
78			Time:         s.now(),
79		})
80	}
81	
82	// withdrawPart 为未关闭工单领用备件：生成同目录唯一且不复用的领用编号，
83	// 追加一条领用履历。失败路径不修改任何业务数据，也不消耗领用编号。
84	func (s *store) withdrawPart(ticketID, partID string, quantity int, note string) (*PartWithdrawal, error) {
85		t := s.findTicket(ticketID)
86		if t == nil {
87			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
88		}
89		if t.Status == ticketClosed {
90			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能领用备件", errConflict, ticketID)
91		}
92		if t.Status == ticketCancelled {
93			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能领用备件", errConflict, ticketID)
94		}
95		if partID == "" {
96			return nil, fmt.Errorf("%w: 备件编号不能为空", errConflict)
97		}
98		if note == "" {
99			return nil, fmt.Errorf("%w: 领用说明不能为空", errConflict)
100		}
101		if quantity < 1 {
102			return nil, fmt.Errorf("%w: 领用数量须为正整数", errConflict)
103		}
104		// 先确认领用编号与履历计数器都能推进，再修改任何业务数据：
105		// 编号耗尽时拒绝领用，不消耗编号，也不产生履历。
106		seq := s.data.NextPartSeq
107		if seq < 1 || seq == math.MaxInt {
108			return nil, fmt.Errorf("%w: 领用编号计数器已耗尽，无法分配新领用编号", errConflict)
109		}
110		eventSeq, err := s.nextEventSeq()
111		if err != nil {
112			return nil, err
113		}
114		p := &PartWithdrawal{
115			ID:       fmt.Sprintf("P%04d", seq),
116			TicketID: t.ID,
117			AssetID:  t.AssetID,
118			PartID:   partID,
119			Quantity: quantity,
120			Note:     note,
121		}
122		s.data.NextPartSeq = seq + 1
123		s.data.Parts = append(s.data.Parts, p)
124		s.appendPartEvent(eventSeq, p, eventPartWithdraw, quantity, note)
125		return p, nil
126	}
127	
128	// returnPart 按领用编号退回备件：作用于该笔领用所属的工单，允许多次部分退回，
129	// 累计不得超过该笔原数量，也不能冲减另一笔。成功时更新累计退回并追加一条退回
130	// 履历。失败路径不修改任何业务数据。
131	func (s *store) returnPart(withdrawalID string, quantity int, reason string) (*PartWithdrawal, *Ticket, error) {
132		p := s.findPart(withdrawalID)
133		if p == nil {
134			return nil, nil, fmt.Errorf("%w: 未知领用编号 %q", errNotFound, withdrawalID)
135		}
136		t := s.findTicket(p.TicketID)
137		if t == nil {
138			return nil, nil, fmt.Errorf("数据内部错误：领用记录 %s 引用的工单不存在", withdrawalID)
139		}
140		if t.Status == ticketClosed {
141			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能退回备件", errConflict, t.ID)
142		}
143		if t.Status == ticketCancelled {
144			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能退回备件", errConflict, t.ID)
145		}
146		if reason == "" {
147			return nil, nil, fmt.Errorf("%w: 退回理由不能为空", errConflict)
148		}
149		if quantity < 1 {
150			return nil, nil, fmt.Errorf("%w: 退回数量须为正整数", errConflict)
151		}
152		if p.Returned+quantity > p.Quantity {
153			return nil, nil, fmt.Errorf(
154				"%w: 领用记录 %s 原数量 %d，已退回 %d，再退 %d 将超过原数量",
155				errConflict, p.ID, p.Quantity, p.Returned, quantity)
156		}
157		eventSeq, err := s.nextEventSeq()
158		if err != nil {
159			return nil, nil, err
160		}
161		p.Returned += quantity
162		s.appendPartEvent(eventSeq, p, eventPartReturn, quantity, reason)
163		return p, t, nil
164	}
