1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"time"
15	)
16	
17	// 资产状态、工单状态与履历类型。
18	const (
19		statusAvailable = "可用"
20		statusRepairing = "维修中"
21		ticketOpen      = "未关闭"
22		ticketClosed    = "已关闭"
23		ticketCancelled = "已取消"
24	
25		eventReport = "报修"
26		eventClose  = "关闭"
27		eventCancel = "取消"
28		eventAssign = "派工"
29	
30		eventPlanCreate = "保养建立"
31		eventPlanDone   = "保养完成"
32	
33		eventPartWithdraw = "领用"
34		eventPartReturn   = "退回"
35	
36		storeVersion = 1
37		dataFileName = "caretrack.json"
38	)
39	
40	var (
41		errNotFound = errors.New("not found")
42		errConflict = errors.New("conflict")
43	)
44	
45	// Asset 为登记的设备资产，ID 即企业资产编号。
46	type Asset struct {
47		ID       string `json:"id"`
48		Name     string `json:"name"`
49		Location string `json:"location"`
50		Status   string `json:"status"`
51	}
52	
53	// Ticket 为维修工单。Assignee 为当前（或终结前最后）负责人，空表示未派工；
54	// AssignedAt/AssignNote 为最近一次派工的变更时间与说明。
55	type Ticket struct {
56		ID           string `json:"id"`
57		AssetID      string `json:"asset_id"`
58		Description  string `json:"description"`
59		RequestID    string `json:"request_id"`
60		Status       string `json:"status"`
61		Result       string `json:"result,omitempty"`
62		CreatedAt    string `json:"created_at"`
63		ClosedAt     string `json:"closed_at,omitempty"`
64		CancelReason string `json:"cancel_reason,omitempty"`
65		CancelledAt  string `json:"cancelled_at,omitempty"`
66		Assignee     string `json:"assignee,omitempty"`
67		AssignedAt   string `json:"assigned_at,omitempty"`
68		AssignNote   string `json:"assign_note,omitempty"`
69	}
70	
71	// Event 为履历条目（报修/派工/关闭/取消/保养建立/保养完成/领用/退回），Seq 决定操作发生顺序。
72	// From/To 仅派工履历使用：原负责人（首次派工为空，展示为“未派工”）与新负责人。
73	// Due/Done/Interval 仅保养履历使用：建立履历含首次到期日（Due）与间隔天数
74	// （Interval），完成履历含周期到期日（Due）与实际完成日（Done）。
75	// PartID/Quantity/WithdrawalID 仅备件履历使用：领用与退回履历都携带备件编号、
76	// 数量与所属领用编号；Content 分别为领用说明与退回理由。
77	type Event struct {
78		Seq          int       `json:"-"`
79		AssetID      string    `json:"-"`
80		TicketID     string    `json:"-"`
81		Kind         string    `json:"-"`
82		Content      string    `json:"-"`
83		From         string    `json:"-"`
84		To           string    `json:"-"`
85		Due          string    `json:"-"`
86		Done         string    `json:"-"`
87		Interval     int       `json:"-"`
88		PartID       string    `json:"-"`
89		Quantity     int       `json:"-"`
90		WithdrawalID string    `json:"-"`
91		Time         time.Time `json:"-"`
92	}
93	
94	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
95	type eventJSON struct {
96		Seq          int    `json:"seq"`
97		AssetID      string `json:"asset_id"`
98		TicketID     string `json:"ticket_id,omitempty"`
99		Kind         string `json:"kind"`
100		Content      string `json:"content"`
101		From         string `json:"from,omitempty"`
102		To           string `json:"to,omitempty"`
103		Due          string `json:"due,omitempty"`
104		Done         string `json:"done,omitempty"`
105		Interval     int    `json:"interval,omitempty"`
106		PartID       string `json:"part_id,omitempty"`
107		Quantity     int    `json:"quantity,omitempty"`
108		WithdrawalID string `json:"withdrawal_id,omitempty"`
109		Time         string `json:"time"`
110	}
111	
112	func (e Event) toJSON() eventJSON {
113		return eventJSON{
114			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
115			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
116			Due: e.Due, Done: e.Done, Interval: e.Interval,
117			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
118			// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
119			// 因此既有整秒台账的字节表示不变，而旧库中带小数秒的履历时间
120			// 在重新保存（含导入合并后的提交）时也不会被截断。
121			Time: e.Time.Format(time.RFC3339Nano),
122		}
123	}
124	
125	func (e eventJSON) toEvent() (Event, error) {
126		t, err := time.Parse(time.RFC3339, e.Time)
127		if err != nil {
128			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
129		}
130		return Event{
131			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
132			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
133			Due: e.Due, Done: e.Done, Interval: e.Interval,
134			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
135			Time: t,
136		}, nil
137	}
138	
139	// PartWithdrawal 为一笔备件领用记录，ID 即领用编号（同目录唯一、不复用）。
140	// 数量表示工单用量；Returned 为累计退回数量，净量 = Quantity - Returned。
141	// 工单关闭或取消后记录与净量保留，不清零。
142	type PartWithdrawal struct {
143		ID       string `json:"id"`
144		TicketID string `json:"ticket_id"`
145		AssetID  string `json:"asset_id"`
146		PartID   string `json:"part_id"`
147		Quantity int    `json:"quantity"`
148		Note     string `json:"note"`
149		Returned int    `json:"returned"`
150	}
151	
152	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
153	// 它既不是资产编号也不是工单编号。
154	type requestBinding struct {
155		RequestID   string `json:"request_id"`
156		AssetID     string `json:"asset_id"`
157		Description string `json:"description"`
158		TicketID    string `json:"ticket_id"`
159	}
160	
161	// storeData 是一次成功写操作共同生效的完整业务数据。
162	type storeData struct {
163		Version       int               `json:"version"`
164		Assets        []*Asset          `json:"assets"`
165		Tickets       []*Ticket         `json:"tickets"`
166		Events        []Event           `json:"-"`
167		EventsJSON    []eventJSON       `json:"events"`
168		Requests      []requestBinding  `json:"requests"`
169		Plans         []*Plan           `json:"plans"`
170		Parts         []*PartWithdrawal `json:"parts"`
171		NextTicketSeq int               `json:"next_ticket_seq"`
172		NextPartSeq   int               `json:"next_part_seq"`
173	}
174	
175	type store struct {
176		dir  string
177		data *storeData
178		now  func() time.Time
179	}
180	
181	func newStoreData() *storeData {
182		return &storeData{
183			Version:       storeVersion,
184			Assets:        []*Asset{},
185			Tickets:       []*Ticket{},
186			Events:        []Event{},
187			EventsJSON:    []eventJSON{},
188			Requests:      []requestBinding{},
189			Plans:         []*Plan{},
190			Parts:         []*PartWithdrawal{},
191			NextTicketSeq: 1,
192			NextPartSeq:   1,
193		}
194	}
195	
196	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
197	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
198	func openStore(dir string) (*store, error) {
199		return loadStore(dir, true)
200	}
201	
202	// openSourceStore 以只读用途打开导入源数据目录：与 openStore 做同样的整库
203	// 一致性检查，但源台账必须已存在——不存在时报错，绝不能当空库初始化。
204	func openSourceStore(dir string) (*store, error) {
205		return loadStore(dir, false)
206	}
207	
208	func loadStore(dir string, allowMissing bool) (*store, error) {
209		path := filepath.Join(dir, dataFileName)
210		raw, err := os.ReadFile(path)
211		if err != nil {
212			if errors.Is(err, os.ErrNotExist) {
213				if allowMissing {
214					return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
215				}
216				return nil, fmt.Errorf("源数据文件 %s 不存在：源台账必须已存在，不能当空库处理", path)
217			}
218			return nil, fmt.Errorf("读取数据文件失败: %w", err)
219		}
220		if len(bytes.TrimSpace(raw)) == 0 {
221			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
222		}
223		var d storeData
224		if err := json.Unmarshal(raw, &d); err != nil {
225			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
226		}
227		if d.EventsJSON != nil {
228			d.Events = make([]Event, len(d.EventsJSON))
229			for i, ej := range d.EventsJSON {
230				ev, err := ej.toEvent()
231				if err != nil {
232					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
233				}
234				d.Events[i] = ev
235			}
236		}
237		// 无保养字段的有效旧库直接使用：缺省视为没有任何保养计划。
238		if d.Plans == nil {
239			d.Plans = []*Plan{}
240		}
241		// 无备件字段的有效旧库直接使用：缺省视为没有任何备件领用记录，
242		// 领用编号计数器从 1 开始。
243		if d.Parts == nil {
244			d.Parts = []*PartWithdrawal{}
245		}
246		if d.NextPartSeq == 0 && len(d.Parts) == 0 {
247			d.NextPartSeq = 1
248		}
249		if err := validateData(&d); err != nil {
250			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
251		}
252		return &store{dir: dir, data: &d, now: time.Now}, nil
253	}
254	
255	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
256	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
257	func parseTicketSeq(id string) (int, bool) {
258		if !strings.HasPrefix(id, "T") {
259			return 0, false
260		}
261		n, err := strconv.Atoi(id[1:])
262		if err != nil || n < 1 {
263			return 0, false
264		}
265		if fmt.Sprintf("T%04d", n) != id {
266			return 0, false
267		}
268		return n, true
269	}
270	
271	// parsePartSeq 解析 P 加补零正整数序号形式的领用编号，返回序号。
272	// 编号必须与 fmt.Sprintf("P%04d", n)（n ≥ 1）完全一致，否则视为非法。
273	func parsePartSeq(id string) (int, bool) {
274		if !strings.HasPrefix(id, "P") {
275			return 0, false
276		}
277		n, err := strconv.Atoi(id[1:])
278		if err != nil || n < 1 {
279			return 0, false
280		}
281		if fmt.Sprintf("P%04d", n) != id {
282			return 0, false
283		}
284		return n, true
285	}
286	
287	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
288	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
289	// 不做任何修复：不补字段、不重编号、不删除记录。
290	func validateData(d *storeData) error {
291		if d.Version != storeVersion {
292			return fmt.Errorf("不支持的数据版本 %d", d.Version)
293		}
294		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil || d.Plans == nil || d.Parts == nil {
295			return errors.New("缺少必要的数据段")
296		}
297		assets := map[string]*Asset{}
298		for _, a := range d.Assets {
299			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
300				return errors.New("数据矛盾：存在字段不完整的资产记录")
301			}
302			if a.Status != statusAvailable && a.Status != statusRepairing {
303				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
304			}
305			if assets[a.ID] != nil {
306				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
307			}
308			assets[a.ID] = a
309		}
310		tickets := map[string]*Ticket{}
311		maxTicketSeq := 0
312		for _, t := range d.Tickets {
313			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
314				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
315			}
316			n, ok := parseTicketSeq(t.ID)
317			if !ok {
318				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
319			}
320			if n > maxTicketSeq {
321				maxTicketSeq = n
322			}
323			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
324				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
325			}
326			if assets[t.AssetID] == nil {
327				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
328			}
329			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
330				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
331			}
332			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
333				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
334			}
335			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
336				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
337			}
338			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
339				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
340			}
341			if t.Assignee == "" {
342				if t.AssignedAt != "" || t.AssignNote != "" {
343					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
344				}
345			} else if t.AssignedAt == "" || t.AssignNote == "" {
346				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
347			}
348			if tickets[t.ID] != nil {
349				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
350			}
351			tickets[t.ID] = t
352		}
353		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
354		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
355			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
356				d.NextTicketSeq, maxTicketSeq)
357		}
358		// 备件领用记录：编号唯一且为 P 加补零正整数序号，归属存在的工单且资产归属
359		// 与工单一致，数量为正，累计退回在 [0, 原数量] 内；与履历的接续在下方按
360		// 履历序号重放时核对。
361		parts := map[string]*PartWithdrawal{}
362		maxPartSeq := 0
363		for _, p := range d.Parts {
364			if p == nil || p.ID == "" || p.TicketID == "" || p.AssetID == "" || p.PartID == "" || p.Note == "" {
365				return errors.New("数据矛盾：存在字段不完整的备件领用记录")
366			}
367			n, ok := parsePartSeq(p.ID)
368			if !ok {
369				return fmt.Errorf("计数器矛盾：领用编号 %q 不是 P 加补零正整数序号的形式", p.ID)
370			}
371			if n > maxPartSeq {
372				maxPartSeq = n
373			}
374			if p.Quantity < 1 {
375				return fmt.Errorf("数据矛盾：领用记录 %s 的数量 %d 不是正整数", p.ID, p.Quantity)
376			}
377			if p.Returned < 0 || p.Returned > p.Quantity {
378				return fmt.Errorf("数据矛盾：领用记录 %s 的累计退回 %d 超出原数量 %d", p.ID, p.Returned, p.Quantity)
379			}
380			t := tickets[p.TicketID]
381			if t == nil {
382				return fmt.Errorf("数据矛盾：领用记录 %s 引用了不存在的工单 %s", p.ID, p.TicketID)
383			}
384			if t.AssetID != p.AssetID {
385				return fmt.Errorf("数据矛盾：领用记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
386					p.ID, p.AssetID, t.ID, t.AssetID)
387			}
388			if parts[p.ID] != nil {
389				return fmt.Errorf("数据矛盾：领用编号 %s 重复", p.ID)
390			}
391			parts[p.ID] = p
392		}
393		// 下一领用序号必须为正并大于全部已用序号（允许有间隔）。
394		if d.NextPartSeq < 1 || d.NextPartSeq <= maxPartSeq {
395			return fmt.Errorf("计数器矛盾：下一领用序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
396				d.NextPartSeq, maxPartSeq)
397		}
398		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
399		boundReq := map[string]bool{}
400		boundTicket := map[string]bool{}
401		for _, r := range d.Requests {
402			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
403				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
404			}
405			if boundReq[r.RequestID] {
406				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
407			}
408			boundReq[r.RequestID] = true
409			t := tickets[r.TicketID]
410			if t == nil {
411				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
412			}
413			if t.RequestID != r.RequestID {
414				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
415					r.TicketID, t.RequestID, r.RequestID)
416			}
417			if r.AssetID != t.AssetID || r.Description != t.Description {
418				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
419					r.RequestID, t.ID)
420			}
421			boundTicket[r.TicketID] = true
422		}
423		for _, t := range d.Tickets {
424			if !boundTicket[t.ID] {
425				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
426			}
427		}
428		// 状态：每项资产最多一张未关闭工单，有则“维修中”，无则“可用”。
429		openCount := map[string]int{}
430		for _, t := range d.Tickets {
431			if t.Status == ticketOpen {
432				openCount[t.AssetID]++
433			}
434		}
435		for _, a := range d.Assets {
436			c := openCount[a.ID]
437			if c > 1 {
438				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
439			}
440			want := statusAvailable
441			if c == 1 {
442				want = statusRepairing
443			}
444			if a.Status != want {
445				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
446					a.ID, c, want, a.Status)
447			}
448		}
449		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
450		seenSeq := map[int]bool{}
451		reportSeq := map[string]int{}
452		closeSeq := map[string]int{}
453		cancelSeq := map[string]int{}
454		reportCount := map[string]int{}
455		closeCount := map[string]int{}
456		cancelCount := map[string]int{}
457		for i := range d.Events {
458			e := &d.Events[i]
459			if e.Seq < 1 {
460				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
461			}
462			if seenSeq[e.Seq] {
463				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
464			}
465			seenSeq[e.Seq] = true
466			if e.AssetID == "" || e.Kind == "" || e.Content == "" {
467				return errors.New("履历矛盾：存在字段不完整的履历记录")
468			}
469			if e.Kind == eventPlanCreate || e.Kind == eventPlanDone {
470				// 保养履历：不属于任何工单，不携带派工字段；日期与间隔在此核对，
471				// 建立及完成链的接续在下方按序号重放时核对。
472				if e.TicketID != "" || e.From != "" || e.To != "" {
473					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号或派工人员字段", e.Seq, e.Kind)
474				}
475				due, err := parseDate(e.Due)
476				if err != nil {
477					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录到期日无效", e.Seq, e.Kind)
478				}
479				if e.Kind == eventPlanCreate {
480					if e.Done != "" {
481						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录不应带有完成日", e.Seq)
482					}
483					if e.Interval < 1 {
484						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录间隔天数须为正整数", e.Seq)
485					}
486				} else {
487					if e.Interval != 0 {
488						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录不应带有间隔天数", e.Seq)
489					}
490					done, err := parseDate(e.Done)
491					if err != nil {
492						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录完成日无效", e.Seq)
493					}
494					if done < due {
495						return fmt.Errorf("履历矛盾：履历序号 %d 的完成日早于周期到期日", e.Seq)
496					}
497				}
498				continue
499			}
500			if e.TicketID == "" {
501				return errors.New("履历矛盾：存在字段不完整的履历记录")
502			}
503			if e.Due != "" || e.Done != "" || e.Interval != 0 {
504				return fmt.Errorf("履历矛盾：履历序号 %d 的维修履历不应带有保养字段", e.Seq)
505			}
506			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
507				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
508			}
509			if e.Kind == eventAssign {
510				if e.To == "" {
511					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
512				}
513				if e.From == e.To {
514					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
515				}
516			}
517			t := tickets[e.TicketID]
518			if t == nil || assets[e.AssetID] == nil {
519				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
520			}
521			if e.AssetID != t.AssetID {
522				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
523					e.Seq, e.AssetID, t.ID, t.AssetID)
524			}
525			switch e.Kind {
526			case eventReport:
527				if e.Content != t.Description {
528					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
529				}
530				reportCount[t.ID]++
531				reportSeq[t.ID] = e.Seq
532			case eventClose:
533				if e.Content != t.Result {
534					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
535				}
536				closeCount[t.ID]++
537				closeSeq[t.ID] = e.Seq
538			case eventCancel:
539				if e.Content != t.CancelReason {
540					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
541				}
542				cancelCount[t.ID]++
543				cancelSeq[t.ID] = e.Seq
544			case eventAssign:
545				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
546				// 在下方按序号重放时核对。
547			case eventPartWithdraw, eventPartReturn:
548				// 内容即领用说明或退回理由（非空已检查）；备件字段在此核对，
549				// 与领用记录的接续及累计退回在下方按序号重放时核对。
550				if e.PartID == "" || e.WithdrawalID == "" {
551					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少备件编号或领用编号", e.Seq, e.Kind)
552				}
553				if e.Quantity < 1 {
554					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录数量 %d 不是正整数", e.Seq, e.Kind, e.Quantity)
555				}
556				if _, ok := parsePartSeq(e.WithdrawalID); !ok {
557					return fmt.Errorf("履历矛盾：履历序号 %d 的领用编号 %q 不是 P 加补零正整数序号的形式",
558						e.Seq, e.WithdrawalID)
559				}
560			default:
561				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
562			}
563		}
564		for _, t := range d.Tickets {
565			if reportCount[t.ID] != 1 {
566				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
567			}
568			if t.Status == ticketClosed {
569				if closeCount[t.ID] != 1 {
570					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
571				}
572				if closeSeq[t.ID] <= reportSeq[t.ID] {
573					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
574						t.ID, closeSeq[t.ID], reportSeq[t.ID])
575				}
576			} else if closeCount[t.ID] != 0 {
577				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
578			}
579			if t.Status == ticketCancelled {
580				if cancelCount[t.ID] != 1 {
581					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
582				}
583				if cancelSeq[t.ID] <= reportSeq[t.ID] {
584					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
585						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
586				}
587			} else if cancelCount[t.ID] != 0 {
588				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
589			}
590		}
591		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
592		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
593		sorted := make([]Event, len(d.Events))
594		copy(sorted, d.Events)
595		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
596		derivedTicket := map[string]string{}
597		derivedOpen := map[string]string{}
598		derivedAssignee := map[string]string{}
599		derivedNote := map[string]string{}
600		withdrawSeq := map[string]int{}
601		derivedReturned := map[string]int{}
602		for _, e := range sorted {
603			switch e.Kind {
604			case eventReport:
605				if derivedTicket[e.TicketID] != "" {
606					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
607				}
608				if prev := derivedOpen[e.AssetID]; prev != "" {
609					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
610						e.AssetID, prev, e.TicketID)
611				}
612				derivedTicket[e.TicketID] = ticketOpen
613				derivedOpen[e.AssetID] = e.TicketID
614			case eventAssign:
615				if derivedTicket[e.TicketID] != ticketOpen {
616					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
617				}
618				if e.From != derivedAssignee[e.TicketID] {
619					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
620						e.TicketID, e.Seq, e.From)
621				}
622				derivedAssignee[e.TicketID] = e.To
623				derivedNote[e.TicketID] = e.Content
624			case eventClose:
625				if derivedTicket[e.TicketID] != ticketOpen {
626					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
627				}
628				derivedTicket[e.TicketID] = ticketClosed
629				delete(derivedOpen, e.AssetID)
630			case eventCancel:
631				if derivedTicket[e.TicketID] != ticketOpen {
632					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
633				}
634				derivedTicket[e.TicketID] = ticketCancelled
635				delete(derivedOpen, e.AssetID)
636			case eventPartWithdraw:
637				// 领用须在报修之后、终结之前；履历与领用记录的业务字段必须一致。
638				if derivedTicket[e.TicketID] != ticketOpen {
639					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现领用履历（序号 %d）",
640						e.TicketID, e.Seq)
641				}
642				p := parts[e.WithdrawalID]
643				if p == nil {
644					return fmt.Errorf("履历矛盾：领用履历（序号 %d）引用了不存在的领用记录 %s",
645						e.Seq, e.WithdrawalID)
646				}
647				if withdrawSeq[p.ID] != 0 {
648					return fmt.Errorf("履历矛盾：领用记录 %s 有多条领用履历", p.ID)
649				}
650				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID ||
651					p.Quantity != e.Quantity || p.Note != e.Content {
652					return fmt.Errorf("履历矛盾：领用履历（序号 %d）与领用记录 %s 的工单、资产、备件、数量或说明不一致",
653						e.Seq, p.ID)
654				}
655				withdrawSeq[p.ID] = e.Seq
656			case eventPartReturn:
657				// 退回须在报修之后、终结之前，且指向先前已领用的记录；
658				// 累计退回不得超过该笔原数量。
659				if derivedTicket[e.TicketID] != ticketOpen {
660					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现退回履历（序号 %d）",
661						e.TicketID, e.Seq)
662				}
663				p := parts[e.WithdrawalID]
664				if p == nil {
665					return fmt.Errorf("履历矛盾：退回履历（序号 %d）引用了不存在的领用记录 %s",
666						e.Seq, e.WithdrawalID)
667				}
668				if withdrawSeq[p.ID] == 0 {
669					return fmt.Errorf("履历矛盾：退回履历（序号 %d）出现在领用记录 %s 的领用履历之前",
670						e.Seq, p.ID)
671				}
672				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID {
673					return fmt.Errorf("履历矛盾：退回履历（序号 %d）与领用记录 %s 的工单、资产或备件不一致",
674						e.Seq, p.ID)
675				}
676				derivedReturned[p.ID] += e.Quantity
677				if derivedReturned[p.ID] > p.Quantity {
678					return fmt.Errorf("履历矛盾：领用记录 %s 的累计退回 %d 超过原数量 %d",
679						p.ID, derivedReturned[p.ID], p.Quantity)
680				}
681			}
682		}
683		for _, t := range d.Tickets {
684			if derivedTicket[t.ID] != t.Status {
685				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
686					t.ID, derivedTicket[t.ID], t.Status)
687			}
688			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
689			if derivedAssignee[t.ID] != t.Assignee {
690				return fmt.Errorf("状态矛盾：按履历推出工单 %s 最后负责人为 %q，与保存的 %q 不符",
691					t.ID, derivedAssignee[t.ID], t.Assignee)
692			}
693			if t.Assignee != "" && derivedNote[t.ID] != t.AssignNote {
694				return fmt.Errorf("状态矛盾：工单 %s 保存的派工说明与最后一次派工履历不一致", t.ID)
695			}
696		}
697		// 每笔领用记录恰有一条领用履历；按履历重放得到的累计退回须与保存值一致。
698		for _, p := range d.Parts {
699			if withdrawSeq[p.ID] == 0 {
700				return fmt.Errorf("履历矛盾：领用记录 %s 缺少对应的领用履历", p.ID)
701			}
702			if derivedReturned[p.ID] != p.Returned {
703				return fmt.Errorf("数据矛盾：按履历推出领用记录 %s 的累计退回为 %d，与保存的 %d 不符",
704					p.ID, derivedReturned[p.ID], p.Returned)
705			}
706		}
707		for _, a := range d.Assets {
708			want := statusAvailable
709			if derivedOpen[a.ID] != "" {
710				want = statusRepairing
711			}
712			if a.Status != want {
713				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
714					a.ID, want, a.Status)
715			}
716		}
717		// 保养计划：归属存在的资产、每项资产最多一个、日期有效、间隔为正整数。
718		plans := map[string]*Plan{}
719		for _, p := range d.Plans {
720			if p == nil || p.AssetID == "" || p.Content == "" {
721				return errors.New("数据矛盾：存在字段不完整的保养计划")
722			}
723			if assets[p.AssetID] == nil {
724				return fmt.Errorf("数据矛盾：保养计划引用了不存在的资产 %s", p.AssetID)
725			}
726			if plans[p.AssetID] != nil {
727				return fmt.Errorf("数据矛盾：资产 %s 有多个保养计划，最多允许一个", p.AssetID)
728			}
729			if _, err := parseDate(p.FirstDue); err != nil {
730				return fmt.Errorf("数据矛盾：资产 %s 保养计划的首次到期日无效", p.AssetID)
731			}
732			if p.IntervalDays < 1 {
733				return fmt.Errorf("数据矛盾：资产 %s 保养计划的间隔天数须为正整数", p.AssetID)
734			}
735			if _, err := parseDate(p.NextDue); err != nil {
736				return fmt.Errorf("数据矛盾：资产 %s 保养计划的下一到期日无效", p.AssetID)
737			}
738			plans[p.AssetID] = p
739		}
740		// 保养履历链：每个计划恰有一条建立履历（内容、首次到期日、间隔与计划一致），
741		// 完成履历按序号接续（周期到期日须等于当前下一到期日，完成日不早于它），
742		// 由履历推出的下一到期日须与计划保存的一致。没有计划的资产不得有保养履历。
743		maintCreate := map[string]int{}
744		derivedDue := map[string]string{}
745		for _, e := range sorted {
746			if e.Kind != eventPlanCreate && e.Kind != eventPlanDone {
747				continue
748			}
749			p := plans[e.AssetID]
750			if p == nil {
751				return fmt.Errorf("履历矛盾：资产 %s 没有保养计划，却存在保养履历（序号 %d）", e.AssetID, e.Seq)
752			}
753			if e.Kind == eventPlanCreate {
754				if maintCreate[e.AssetID] != 0 {
755					return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", e.AssetID)
756				}
757				maintCreate[e.AssetID] = e.Seq
758				if e.Content != p.Content || e.Due != p.FirstDue || e.Interval != p.IntervalDays {
759					return fmt.Errorf("履历矛盾：资产 %s 的保养建立履历与计划内容、首次到期日或间隔不一致", e.AssetID)
760				}
761				derivedDue[e.AssetID] = e.Due
762				continue
763			}
764			if maintCreate[e.AssetID] == 0 {
765				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）出现在建立履历之前", e.AssetID, e.Seq)
766			}
767			if e.Due != derivedDue[e.AssetID] {
768				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续",
769					e.AssetID, e.Seq, e.Due, derivedDue[e.AssetID])
770			}
771			first, _ := parseDate(p.FirstDue)
772			done, _ := parseDate(e.Done)
773			next, ok := nextDueAfter(first, int64(p.IntervalDays), done)
774			if !ok {
775				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
776					e.AssetID, e.Seq)
777			}
778			derivedDue[e.AssetID] = formatDate(next)
779		}
780		for _, p := range d.Plans {
781			if maintCreate[p.AssetID] == 0 {
782				return fmt.Errorf("履历矛盾：资产 %s 的保养计划应有恰一条建立履历，实际没有", p.AssetID)
783			}
784			if derivedDue[p.AssetID] != p.NextDue {
785				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的下一到期日为 %s，与保存的 %s 不符",
786					p.AssetID, derivedDue[p.AssetID], p.NextDue)
787			}
788		}
789		return nil
790	}
