792	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
793	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
794	// 保持不变，不留下部分业务变化。
795	func (s *store) save() error {
796		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
797		for i, e := range s.data.Events {
798			s.data.EventsJSON[i] = e.toJSON()
799		}
800		if err := validateData(s.data); err != nil {
801			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
802		}
803		var buf bytes.Buffer
804		enc := json.NewEncoder(&buf)
805		enc.SetIndent("", "  ")
806		if err := enc.Encode(s.data); err != nil {
807			return fmt.Errorf("编码数据失败: %w", err)
808		}
809		if err := os.MkdirAll(s.dir, 0o755); err != nil {
810			return fmt.Errorf("创建数据目录失败: %w", err)
811		}
812		path := filepath.Join(s.dir, dataFileName)
813		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
814		if err != nil {
815			return fmt.Errorf("创建临时数据文件失败: %w", err)
816		}
817		tmpName := tmp.Name()
818		abort := func(err error) error {
819			_ = tmp.Close()
820			_ = os.Remove(tmpName)
821			return err
822		}
823		if _, err := tmp.Write(buf.Bytes()); err != nil {
824			abort(nil)
825			return fmt.Errorf("写入数据失败: %w", err)
826		}
827		if err := tmp.Sync(); err != nil {
828			abort(nil)
829			return fmt.Errorf("写入数据失败: %w", err)
830		}
831		if err := tmp.Close(); err != nil {
832			_ = os.Remove(tmpName)
833			return fmt.Errorf("写入数据失败: %w", err)
834		}
835		if err := os.Rename(tmpName, path); err != nil {
836			_ = os.Remove(tmpName)
837			return fmt.Errorf("保存数据失败: %w", err)
838		}
839		return nil
840	}
