889	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
890	func (s *store) nextEventSeq() (int, error) {
891		maxSeq := 0
892		for _, e := range s.data.Events {
893			if e.Seq > maxSeq {
894				maxSeq = e.Seq
895			}
896		}
897		if maxSeq == math.MaxInt {
898			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
899		}
900		return maxSeq + 1, nil
901	}
