903	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
904	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
905	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
906		s.data.Events = append(s.data.Events, Event{
907			Seq:      seq,
908			AssetID:  assetID,
909			TicketID: ticketID,
910			Kind:     kind,
911			Content:  content,
912			From:     from,
913			To:       to,
914			Time:     s.now(),
915		})
916	}
