918	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
919		if s.findAsset(id) != nil {
920			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
921		}
922		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
923		s.data.Assets = append(s.data.Assets, a)
924		return a, nil
925	}
