927	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
928	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
929	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
930		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
931		// 资产或描述不同 => 拒绝。
932		if r := s.findRequest(requestID); r != nil {
933			if r.AssetID != assetID || r.Description != description {
934				return nil, false, fmt.Errorf(
935					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
936					errConflict, requestID, r.AssetID)
937			}
938			t := s.findTicket(r.TicketID)
939			if t == nil {
940				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
941			}
942			return t, true, nil
943		}
944	
945		asset := s.findAsset(assetID)
946		if asset == nil {
947			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
948		}
949		if t := s.openTicketOf(assetID); t != nil {
950			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
951		}
952		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
953		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
954		seq := s.data.NextTicketSeq
955		if seq < 1 || seq == math.MaxInt {
956			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
957		}
958		eventSeq, err := s.nextEventSeq()
959		if err != nil {
960			return nil, false, err
961		}
962		t := &Ticket{
963			ID:          fmt.Sprintf("T%04d", seq),
964			AssetID:     assetID,
965			Description: description,
966			RequestID:   requestID,
967			Status:      ticketOpen,
968			CreatedAt:   s.now().Format(time.RFC3339),
969		}
970		s.data.NextTicketSeq = seq + 1
971		s.data.Tickets = append(s.data.Tickets, t)
972		s.data.Requests = append(s.data.Requests, requestBinding{
973			RequestID:   requestID,
974			AssetID:     assetID,
975			Description: description,
976			TicketID:    t.ID,
977		})
978		asset.Status = statusRepairing
979		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
980		return t, false, nil
981	}
982	
983	// closeTicket 关闭未关闭工单并把资产恢复为可用。
984	// 失败路径不修改任何业务数据。
985	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
986		t := s.findTicket(ticketID)
987		if t == nil {
988			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
989		}
990		if t.Status == ticketCancelled {
991			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
992		}
993		if t.Status != ticketOpen {
994			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
995		}
996		asset := s.findAsset(t.AssetID)
997		if asset == nil {
998			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
999		}
1000		eventSeq, err := s.nextEventSeq()
1001		if err != nil {
1002			return nil, nil, err
1003		}
1004		t.Status = ticketClosed
1005		t.Result = result
1006		t.ClosedAt = s.now().Format(time.RFC3339)
1007		asset.Status = statusAvailable
1008		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1009		return t, asset, nil
1010	}
1011	
1012	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
1013	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
1014	// 失败路径不修改任何业务数据。
1015	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1016		t := s.findTicket(ticketID)
1017		if t == nil {
1018			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1019		}
1020		if t.Status == ticketCancelled {
1021			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
1022		}
1023		if t.Status == ticketClosed {
1024			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
1025		}
1026		asset := s.findAsset(t.AssetID)
1027		if asset == nil {
1028			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1029		}
1030		eventSeq, err := s.nextEventSeq()
1031		if err != nil {
1032			return nil, nil, err
1033		}
1034		t.Status = ticketCancelled
1035		t.CancelReason = reason
1036		t.CancelledAt = s.now().Format(time.RFC3339)
1037		asset.Status = statusAvailable
1038		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1039		return t, asset, nil
1040	}
1041	
1042	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
1043	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
1044	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
1045	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
1046	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
1047	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
1048		t := s.findTicket(ticketID)
1049		if t == nil {
1050			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1051		}
1052		if t.Status == ticketClosed {
1053			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
1054		}
1055		if t.Status == ticketCancelled {
1056			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
1057		}
1058		if assignee == "" {
1059			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
1060		}
1061		if note == "" {
1062			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
1063		}
1064		if t.Assignee == assignee {
1065			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
1066				errConflict, ticketID, assignee)
1067		}
1068		eventSeq, err := s.nextEventSeq()
1069		if err != nil {
1070			return nil, err
1071		}
1072		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
1073		t.Assignee = assignee
1074		t.AssignedAt = s.now().Format(time.RFC3339)
1075		t.AssignNote = note
1076		return t, nil
1077	}
1078

