1	package main
2	
3	import (
4		"errors"
5		"fmt"
6		"io"
7		"math"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12	)
13	
14	// 资产批量导入：把源数据目录中所选资产连同其全部工单、报修请求绑定、
15	// 报修/派工/关闭/取消履历、备件领用记录与保养计划（含保养建立/完成履历）
16	// 复制到目标数据目录。
17	//
18	// 关键规则：
19	//   - 导入是复制：源台账始终只读，不删除、不修改任何源记录；同一台账不能导入自身。
20	//   - 工单编号按源工单序号升序，从目标的下一工单序号重新分配，并同步替换履历与
21	//     请求绑定中的工单引用；目标原有记录不改编号、不改变业务含义。
22	//   - 备件领用编号按源领用顺序（领用序号升序），从目标的下一领用序号重新分配并
23	//     输出映射；领用记录的工单引用与退回履历中的领用引用同步替换，数量、累计退回
24	//     与净量保持。导入的未关闭工单可继续退回。
25	//   - 履历按源履历序号排列，在目标已有最大履历序号之后依次分配新序号，保留原操作
26	//     顺序（不按时间重排）；履历时间保留原瞬间与小数秒精度。导入本身不追加报修
27	//     或其他业务事件。
28	//   - 保养计划随资产原样复制（内容、首次到期日、间隔与下一到期日不变），保养履历
29	//     随资产履历一并复制，完成链自然接续；目标已有计划不受影响。
30	//   - 资产编号在目标已存在，或所选工单的任一请求标识已在目标绑定时，整批拒绝：
31	//     不覆盖、不合并、不改请求标识。
32	//   - 操作前检查源、目标整库一致性，提交前由 save 再检查合并后的数据；整批变化
33	//     一次原子写入目标。任何失败都不改动两边原文件、不留下部分导入、不消耗目标编号。
34	
35	// stringListFlag 收集可重复的 --asset-id 参数。
36	type stringListFlag []string
37	
38	func (f *stringListFlag) String() string { return strings.Join(*f, ",") }
39	
40	func (f *stringListFlag) Set(v string) error {
41		*f = append(*f, v)
42		return nil
43	}
44	
45	// ticketRemap 记录一张工单的原编号与新编号。
46	type ticketRemap struct {
47		OldID string
48		NewID string
49	}
50	
51	// partRemap 记录一笔备件领用的原领用编号与新领用编号。
52	type partRemap struct {
53		OldID string
54		NewID string
55	}
56	
57	// importOutcome 为一次成功导入的结果摘要，用于输出。
58	type importOutcome struct {
59		assetIDs []string
60		tickets  []ticketRemap
61		parts    []partRemap
62		plans    int
63	}
64	
65	func cmdImport(args []string, w io.Writer) error {
66		var opts cmdOptions
67		var sourceDir string
68		var assetIDs stringListFlag
69		fs := newFlagSet("import", &opts)
70		fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
71		fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
72		if err := parseFlags(fs, args); err != nil {
73			return err
74		}
75		if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
76			return err
77		}
78		if len(assetIDs) == 0 {
79			return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
80		}
81		for _, id := range assetIDs {
82			if id == "" {
83				return &usageError{msg: "命令 import 的 --asset-id 不能为空"}
84			}
85		}
86	
87		outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
88		if err != nil {
89			return err
90		}
91		fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
92		if outcome.plans > 0 {
93			fmt.Fprintf(w, "同时导入 %d 项保养计划及其保养履历。\n", outcome.plans)
94		}
95		if len(outcome.tickets) == 0 {
96			fmt.Fprintln(w, "所选资产没有工单，未分配新工单编号。")
97		} else {
98			fmt.Fprintln(w, "工单编号映射（原编号 -> 新编号）:")
99			for _, m := range outcome.tickets {
100				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
101			}
102		}
103		if len(outcome.parts) > 0 {
104			fmt.Fprintln(w, "领用编号映射（原编号 -> 新编号）:")
105			for _, m := range outcome.parts {
106				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
107			}
108		}
109		return nil
110	}
111	
112	// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
113	// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
114	// 两边原文件字节保持不变。
115	func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
116		srcAbs, err := filepath.Abs(sourceDir)
117		if err != nil {
118			return nil, fmt.Errorf("无法解析源数据目录: %w", err)
119		}
120		dstAbs, err := filepath.Abs(targetDir)
121		if err != nil {
122			return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
123		}
124		if srcAbs == dstAbs {
125			return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
126		}
127		// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
128		srcPath := filepath.Join(srcAbs, dataFileName)
129		dstPath := filepath.Join(dstAbs, dataFileName)
130		if fi1, err1 := os.Stat(srcPath); err1 == nil {
131			if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
132				return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
133			}
134		}
135	
136		// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
137		src, err := openSourceStore(srcAbs)
138		if err != nil {
139			return nil, err
140		}
141		// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
142		dst, err := openStore(dstAbs)
143		if err != nil {
144			return nil, err
145		}
146		outcome, err := dst.mergeImport(src, assetIDs)
147		if err != nil {
148			return nil, err
149		}
150		// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
151		if err := dst.save(); err != nil {
152			return nil, err
153		}
154		return outcome, nil
155	}
156	
157	// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
158	// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
159	func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
160		// 重复编号按一项处理，保持首次出现的顺序。
161		selected := map[string]bool{}
162		ids := make([]string, 0, len(assetIDs))
163		for _, id := range assetIDs {
164			if !selected[id] {
165				selected[id] = true
166				ids = append(ids, id)
167			}
168		}
169		// 所选资产必须存在于源，且编号在目标中不存在。
170		assets := make([]*Asset, 0, len(ids))
171		for _, id := range ids {
172			a := src.findAsset(id)
173			if a == nil {
174				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
175			}
176			if s.findAsset(id) != nil {
177				return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
178			}
179			assets = append(assets, a)
180		}
181		// 所选资产的全部工单，按源工单序号升序重新分配编号。
182		tickets := make([]*Ticket, 0)
183		for _, t := range src.data.Tickets {
184			if selected[t.AssetID] {
185				tickets = append(tickets, t)
186			}
187		}
188		sort.SliceStable(tickets, func(i, j int) bool {
189			ni, _ := parseTicketSeq(tickets[i].ID)
190			nj, _ := parseTicketSeq(tickets[j].ID)
191			return ni < nj
192		})
193		// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
194		if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
195			return nil, fmt.Errorf(
196				"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
197				errConflict, s.data.NextTicketSeq, len(tickets))
198		}
199		// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
200		srcReqByTicket := map[string]*requestBinding{}
201		for i := range src.data.Requests {
202			r := &src.data.Requests[i]
203			srcReqByTicket[r.TicketID] = r
204		}
205		for _, t := range tickets {
206			r := srcReqByTicket[t.ID]
207			if r == nil {
208				return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
209			}
210			if s.findRequest(r.RequestID) != nil {
211				return nil, fmt.Errorf(
212					"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
213			}
214		}
215		// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
216		events := make([]Event, 0)
217		for _, e := range src.data.Events {
218			if selected[e.AssetID] {
219				events = append(events, e)
220			}
221		}
222		sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
223		maxSeq := 0
224		for _, e := range s.data.Events {
225			if e.Seq > maxSeq {
226				maxSeq = e.Seq
227			}
228		}
229		// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
230		if len(events) > math.MaxInt-maxSeq {
231			return nil, fmt.Errorf(
232				"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
233				errConflict, maxSeq, len(events))
234		}
235		// 所选工单的全部备件领用记录，按源领用序号升序重新分配领用编号。
236		srcTicketIDs := map[string]bool{}
237		for _, t := range tickets {
238			srcTicketIDs[t.ID] = true
239		}
240		parts := make([]*PartWithdrawal, 0)
241		for _, p := range src.data.Parts {
242			if srcTicketIDs[p.TicketID] {
243				parts = append(parts, p)
244			}
245		}
246		sort.SliceStable(parts, func(i, j int) bool {
247			ni, _ := parsePartSeq(parts[i].ID)
248			nj, _ := parsePartSeq(parts[j].ID)
249			return ni < nj
250		})
251		// 领用编号容量：与 withdrawPart 同一约束，可分配的最大序号为 math.MaxInt-1。
252		if len(parts) > math.MaxInt-s.data.NextPartSeq {
253			return nil, fmt.Errorf(
254				"%w: 目标领用编号容量不足：下一序号 %d 无法容纳 %d 笔导入领用，整批拒绝导入",
255				errConflict, s.data.NextPartSeq, len(parts))
256		}
257	
258		// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
259		// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
260		for _, a := range assets {
261			na := *a
262			s.data.Assets = append(s.data.Assets, &na)
263		}
264		// 所选资产的保养计划原样复制（内容、首次到期日、间隔与下一到期日不变）；
265		// 保养履历已随上方资产履历筛选一并复制，完成链自然接续。目标已有计划不变。
266		planCount := 0
267		for _, p := range src.data.Plans {
268			if selected[p.AssetID] {
269				np := *p
270				s.data.Plans = append(s.data.Plans, &np)
271				planCount++
272			}
273		}
274		outcome := &importOutcome{assetIDs: ids, plans: planCount}
275		remap := map[string]string{}
276		next := s.data.NextTicketSeq
277		for _, t := range tickets {
278			nt := *t
279			nt.ID = fmt.Sprintf("T%04d", next)
280			remap[t.ID] = nt.ID
281			s.data.Tickets = append(s.data.Tickets, &nt)
282			r := srcReqByTicket[t.ID]
283			s.data.Requests = append(s.data.Requests, requestBinding{
284				RequestID:   r.RequestID,
285				AssetID:     r.AssetID,
286				Description: r.Description,
287				TicketID:    nt.ID,
288			})
289			outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
290			next++
291		}
292		s.data.NextTicketSeq = next
293		// 备件领用记录按源领用顺序重新分配领用编号，工单引用同步替换；
294		// 数量、累计退回与说明等业务信息原样保留。
295		partIDs := map[string]string{}
296		nextPart := s.data.NextPartSeq
297		for _, p := range parts {
298			np := *p
299			np.ID = fmt.Sprintf("P%04d", nextPart)
300			np.TicketID = remap[p.TicketID]
301			partIDs[p.ID] = np.ID
302			s.data.Parts = append(s.data.Parts, &np)
303			outcome.parts = append(outcome.parts, partRemap{OldID: p.ID, NewID: np.ID})
304			nextPart++
305		}
306		s.data.NextPartSeq = nextPart
307		seq := maxSeq
308		for _, e := range events {
309			seq++
310			ne := e
311			ne.Seq = seq
312			ne.TicketID = remap[e.TicketID]
313			ne.WithdrawalID = partIDs[e.WithdrawalID]
314			s.data.Events = append(s.data.Events, ne)
315		}
316		return outcome, nil
317	}
318

