841		fs.StringVar(&startText, "start", "", "窗口起点（必填，带时区的 RFC3339 时刻，可含小数秒；包含）")
842		fs.StringVar(&endText, "end", "", "窗口终点（必填，带时区的 RFC3339 时刻，可含小数秒；不包含）")
843		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（可选；缺省统计全部资产）")
844		if err := parseFlags(fs, args); err != nil {
845			return err
846		}
847		if err := requireFlag(fs, startText, "start"); err != nil {
848			return err
849		}
850		if err := requireFlag(fs, endText, "end"); err != nil {
851			return err
852		}
853		start, err := time.Parse(time.RFC3339, startText)
854		if err != nil {
855			return &usageError{msg: fmt.Sprintf("--start 不是带时区的 RFC3339 时刻 %q: %s", startText, err)}
856		}
857		end, err := time.Parse(time.RFC3339, endText)
858		if err != nil {
859			return &usageError{msg: fmt.Sprintf("--end 不是带时区的 RFC3339 时刻 %q: %s", endText, err)}
860		}
861		if !start.Before(end) {
862			return &usageError{msg: fmt.Sprintf("--start（%s）须早于 --end（%s）", startText, endText)}
863		}
864	
865		// openStore 已先做整库一致性检查：损坏或关联矛盾按原规则拒绝（退出码 1）。
866		s, err := openStore(opts.dataDir)
867		if err != nil {
868			return err
869		}
870	
871		var ids []string
872		if assetID != "" {
873			// 未知资产在统计前拒绝（退出码 1）。
874			if s.findAsset(assetID) == nil {
875				return fmt.Errorf("未知资产编号 %q", assetID)
876			}
877			ids = []string{assetID}
878		} else {
879			ids = s.allAssetIDs()
880			if len(ids) == 0 {
881				fmt.Fprintln(w, "没有记录。")
882				fmt.Fprintln(w, "合计: 0 秒")
883				return nil
884			}
885		}
886	
887		// 先算完全部结果再输出：任一资产存在时间异常时整体失败，不输出部分结果。
888		results, err := s.downtimeForAssets(ids, start, end)
889		if err != nil {
890			return err
891		}
892		var total int64
893		if len(results) == 1 {
894			r := results[0]
895			fmt.Fprintf(w, "资产编号: %s\n", r.AssetID)
896			fmt.Fprintf(w, "名称: %s\n", r.Name)
897			fmt.Fprintf(w, "停机秒数: %d\n", r.Seconds)
898			total = r.Seconds
899		} else {
900			fmt.Fprintf(w, "共 %d 项资产:\n", len(results))
901			for _, r := range results {
902				fmt.Fprintf(w, "%s\t%s\t%d\n", r.AssetID, r.Name, r.Seconds)
903				total += r.Seconds
904			}
905		}
906		fmt.Fprintf(w, "合计: %d 秒\n", total)
907		return nil
908	}
909

