387		p, err := s.withdrawPart("T0001", "FILTER-01", 2, "更换滤芯")
388		if err != nil || p.ID != "P0001" {
389			t.Fatalf("旧库首笔领用编号应为 P0001: %v %+v", err, p)
390		}
391		mustSave(t, s)
392		s2, err := openStore(dir)
393		if err != nil {
394			t.Fatalf("领用后重载: %v", err)
395		}
396		if got := s2.findPart("P0001"); got == nil || got.Quantity != 2 {
397			t.Fatalf("重载后领用记录应保持，得到 %+v", got)
398		}
399	}
400	
401	// 失败重载：写入失败保留原文件字节、不留下部分记录、不消耗编号，恢复后可重试。
402	func TestPartSaveFailureLeavesFileUntouched(t *testing.T) {
403		s, dir := newPartStore(t)
404		if _, err := s.withdrawPart("T0001", "FILTER-01", 3, "更换滤芯"); err != nil {
405			t.Fatal(err)
406		}
407		mustSave(t, s)
408		before := readFileBytes(t, dir)
409	
410		if err := os.Chmod(dir, 0o555); err != nil {
411			t.Fatal(err)
412		}
413		s2, err := openStore(dir)
414		if err != nil {
415			t.Fatal(err)
416		}
417		if _, err := s2.withdrawPart("T0001", "ROLLER-02", 1, "搓纸轮"); err != nil {
418			t.Fatal(err)
419		}
420		saveErr := s2.save()
421		if cerr := os.Chmod(dir, 0o755); cerr != nil {
422			t.Fatal(cerr)
423		}
424		if saveErr == nil {
425			t.Skip("当前环境允许只读目录写入，跳过写入失败分支")
426		}
427		if string(readFileBytes(t, dir)) != string(before) {
428			t.Fatal("写入失败不应改动原文件字节")
429		}
430		// 重载后无部分记录、编号未消耗，恢复后可重试。
431		s3, err := openStore(dir)
432		if err != nil {
433			t.Fatalf("写入失败后应可正常重载: %v", err)
434		}
435		if len(s3.data.Parts) != 1 || s3.data.NextPartSeq != 2 {
436			t.Fatal("写入失败不应留下部分记录，也不应消耗领用编号")
437		}
438		p, err := s3.withdrawPart("T0001", "ROLLER-02", 1, "搓纸轮")
439		if err != nil || p.ID != "P0002" {
440			t.Fatalf("恢复后重试应分配 P0002: %v %+v", err, p)
441		}
442		mustSave(t, s3)
443	}
444	
445	// 命令行入口：参数错误退出 2，业务失败退出 1；ticket 按领用顺序显示各笔与
446	// 净量汇总（零值仍显示），history 展示领用、退回履历。
447	func TestPartCommandLine(t *testing.T) {
448		dir := t.TempDir()
449		var out, errOut bytes.Buffer
450		runCmd := func(args ...string) (int, string, string) {
451			out.Reset()
452			errOut.Reset()
453			code := run(append(args, "--data-dir", dir), &out, &errOut)
454			return code, out.String(), errOut.String()
455		}
456	
457		runCmd("register", "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼")
458		runCmd("report", "--asset-id", "EQ-1", "--description", "卡纸", "--request-id", "req-1")
459	
460		// 参数错误：缺说明、数量非正，退出 2。
461		if code, _, _ := runCmd("withdraw", "--ticket-id", "T0001", "--part-id", "F-1", "--quantity", "1"); code != 2 {
462			t.Fatalf("缺少 --note 应退出 2，得到 %d", code)
463		}
464		if code, _, _ := runCmd("withdraw", "--ticket-id", "T0001", "--part-id", "F-1", "--quantity", "0", "--note", "x"); code != 2 {
465			t.Fatalf("数量非正应退出 2，得到 %d", code)
466		}
467		// 业务失败：未知工单领用退出 1。
468		if code, _, _ := runCmd("withdraw", "--ticket-id", "T9999", "--part-id", "F-1", "--quantity", "1", "--note", "x"); code != 1 {
469			t.Fatalf("未知工单领用应退出 1，得到 %d", code)
470		}
471	
472		// 成功领用并输出领用编号。
473		code, o, _ := runCmd("withdraw", "--ticket-id", "T0001", "--part-id", "B-2", "--quantity", "2", "--note", "领用 B")
474		if code != 0 || !strings.Contains(o, "领用编号: P0001") {
475			t.Fatalf("领用应成功并输出 P0001，得到 %d:\n%s", code, o)
476		}
477		runCmd("withdraw", "--ticket-id", "T0001", "--part-id", "A-1", "--quantity", "1", "--note", "领用 A")
478		// 全部退回 A-1：净量零仍显示。
479		code, o, _ = runCmd("return", "--withdrawal-id", "P0002", "--quantity", "1", "--reason", "多余")
480		if code != 0 || !strings.Contains(o, "累计退回: 1") || !strings.Contains(o, "净量: 0") {
481			t.Fatalf("退回应显示累计退回与净量，得到 %d:\n%s", code, o)
482		}
483		// 超额退回退出 1。
484		if code, _, _ := runCmd("return", "--withdrawal-id", "P0001", "--quantity", "3", "--reason", "超额"); code != 1 {
485			t.Fatalf("超额退回应退出 1，得到 %d", code)
486		}
487		// 未知领用编号退出 1。
488		if code, _, _ := runCmd("return", "--withdrawal-id", "P9999", "--quantity", "1", "--reason", "x"); code != 1 {
489			t.Fatalf("未知领用编号应退出 1，得到 %d", code)
490		}
491	
492		// ticket：按领用顺序显示各笔，按备件编号字典序汇总，零值仍显示。
493		code, o, _ = runCmd("ticket", "--ticket-id", "T0001")
494		if code != 0 {
495			t.Fatalf("ticket 查询应成功，得到 %d", code)
496		}
497		i1 := strings.Index(o, "P0001\tB-2\t原数量 2\t累计退回 0\t净量 2")
498		i2 := strings.Index(o, "P0002\tA-1\t原数量 1\t累计退回 1\t净量 0")
499		if i1 < 0 || i2 < 0 || i1 > i2 {
500			t.Fatalf("ticket 应按领用顺序显示各笔记录，得到:\n%s", o)
501		}
502		s1 := strings.Index(o, "A-1\t净量 0")
503		s2 := strings.Index(o, "B-2\t净量 2")
504		if s1 < 0 || s2 < 0 || s1 > s2 {
505			t.Fatalf("ticket 应按备件编号字典序汇总净量（零值仍显示），得到:\n%s", o)
506		}
507	
508		// history：展示领用与退回履历。
509		code, o, _ = runCmd("history", "--asset-id", "EQ-1")
510		if code != 0 || !strings.Contains(o, "领用 工单 T0001: 领用编号 P0001，备件 B-2，数量 2（领用 B）") ||
511			!strings.Contains(o, "退回 工单 T0001: 领用编号 P0002，备件 A-1，数量 1（多余）") {
512			t.Fatalf("history 应展示领用与退回履历，得到 %d:\n%s", code, o)
513		}
514	
515		// 无记录明确提示。
516		runCmd("register", "--asset-id", "EQ-2", "--name", "空调", "--location", "二楼")
517		runCmd("report", "--asset-id", "EQ-2", "--description", "不制冷", "--request-id", "req-2")
518		code, o, _ = runCmd("ticket", "--ticket-id", "T0002")
519		if code != 0 || !strings.Contains(o, "备件领用: 无") {
520			t.Fatalf("无备件记录应明确提示，得到 %d:\n%s", code, o)
521		}
522	}
